hints:
Create `main.tf` with:
terraform {
  required_providers {
    juju = {
      source = "juju/juju"
    }
  }
}
resource "juju_model" "lab_model" {
  name = "tf-iac-lab"
}

tasks.solution:
cat << 'EOF' > main.tf
terraform {
  required_providers {
    juju = {
      source = "juju/juju"
    }
  }
}

resource "juju_model" "lab_model" {
  name = "tf-iac-lab"
}

resource "juju_application" "frontend" {
  name  = "frontend"
  model = juju_model.lab_model.name
  charm {
    name = "ubuntu"
  }
  units = 1
}
EOF

grep -q 'resource "juju_application"' main.tf || cat << 'EOF' >> main.tf
resource "juju_application" "frontend" {
  name  = "frontend"
  model = juju_model.lab_model.name
  charm {
    name = "ubuntu"
  }
  units = 1
}
EOF
